# Hilfsfunktion für die Selbsttests – einfach ausführen, nicht ändern.
import math

def check(name, test):
    try:
        ok = bool(test())
    except Exception as e:
        print(f"❌ {name}: noch nicht gelöst ({type(e).__name__}: {e})")
        return
    print(f"✅ {name}" if ok else f"❌ {name}: Ergebnis stimmt noch nicht")

print("Selbsttests bereit.")

temperatur = 66
if temperatur > 80:
    status = "rot"
elif temperatur > 60:
    status = "gelb"
else:
    status = "grün"
print(f"{temperatur} °C → {status}")

def flaeche_kreis(radius):
    return math.pi * radius ** 2

print(flaeche_kreis(2))
